function writeSyntheticTargetDir(dir, version, overrides = {}) {
  const support = createSyntheticSupportFiles();
  const files = {
    'dist/main.js': createSyntheticMainJs(version),
    'dist/preload.js': createSyntheticPreloadJs(version),
    ...support,
    ...overrides,
  };
  for (const [rel, content] of Object.entries(files)) {
    const outPath = path.join(dir, ...rel.split('/'));
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, content, 'utf8');
  }
  const ymlPath = path.join(dir, 'app-update.yml');
  fs.writeFileSync(ymlPath, 'provider: generic\nurl: http://127.0.0.1:9/agm-update-disabled/\nupdaterCacheDirName: antigravity\n', 'utf8');
  return ymlPath;
}

function runPatcher(targetDir, ymlPath) {
  const args = [PATCH_JS, targetDir];
  if (ymlPath) args.push('--update-yml', ymlPath);
  const res = spawnSync(process.execPath, args, { encoding: 'utf8', timeout: 30000 });
  return { status: res.status, stdout: res.stdout || '', stderr: res.stderr || '' };
}

// ---------------------------------------------------------------------------
// Fake Electron WebContents / ipcMain
// ---------------------------------------------------------------------------
function makeFrame(url) {
  return { url: url || 'file:///app/index.html', detached: false, isDestroyed: () => false };
}
function makeWebContents(id, url) {
  const listeners = new Map();
  const wc = {
    id: id,
    destroyed: false,
    mainFrame: makeFrame(url),
    isDestroyed() { return wc.destroyed; },
    getURL() { return wc.mainFrame.url; },
    on(ev, fn) {
      if (!listeners.has(ev)) listeners.set(ev, []);
      listeners.get(ev).push(fn);
      return wc;
    },
    once(ev, fn) {
      const wrapped = (...args) => { wc.removeListener(ev, wrapped); fn(...args); };
      return wc.on(ev, wrapped);
    },
    removeListener(ev, fn) {
      const arr = listeners.get(ev) || [];
      const i = arr.indexOf(fn);
      if (i >= 0) arr.splice(i, 1);
      return wc;
    },
    emit(ev, ...args) {
      for (const fn of [...(listeners.get(ev) || [])]) fn(...args);
    },
    listenerCount(ev) { return (listeners.get(ev) || []).length; },
  };
  return wc;
}
function makeIpcMain() {
  const handlers = new Map();
  const listeners = new Map();
  return {
    handlers,
    listeners,
    handle(ch, fn) {
      if (handlers.has(ch)) throw new Error('duplicate handler ' + ch);
      handlers.set(ch, fn);
    },
    removeHandler(ch) { handlers.delete(ch); },
    on(ch, fn) {
      if (!listeners.has(ch)) listeners.set(ch, []);
      listeners.get(ch).push(fn);
    },
    removeListener(ch, fn) {
      const arr = listeners.get(ch) || [];
      const i = arr.indexOf(fn);
      if (i >= 0) arr.splice(i, 1);
    },
    emit(ch, ...args) {
      for (const fn of [...(listeners.get(ch) || [])]) fn(...args);
    },
  };
}
function eventFor(wc, frame) {
  return { sender: wc, senderFrame: frame === undefined ? wc.mainFrame : frame };
}
function invokeSync(ipcMain, ch, event, ...args) {
  const fn = ipcMain.handlers.get(ch);
  if (!fn) throw new Error('handler not registered: ' + ch);
  return fn(event, ...args);
}
function expectDenied(ipcMain, ch, event, ...args) {
  try {
    invokeSync(ipcMain, ch, event, ...args);
    return { denied: false, error: null };
  } catch (e) {
    return { denied: true, error: e };
  }
}

// ---------------------------------------------------------------------------
// Patched main.js VM harness (loads the real patched main process code)
// ---------------------------------------------------------------------------
function buildFsProxy(counters) {
  const WRITE_OPS = new Set(['writeFileSync', 'appendFileSync', 'mkdirSync', 'renameSync', 'unlinkSync', 'rmSync', 'rmdirSync', 'copyFileSync', 'createWriteStream']);
  return new Proxy(fs, {
    get(target, prop) {
      const value = target[prop];
      if (WRITE_OPS.has(prop)) {
        return (...args) => { counters.writeOps.push(String(prop)); return value(...args); };
      }
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
}

async function loadPatchedMain(mainSrc, options = {}) {
  const handlers = new Map();
  const warnings = [];
  const writeOps = [];
  const spawnOps = [];
  const fakeConsole = {
    log() {},
    warn: (...a) => warnings.push(a.join(' ')),
    error: (...a) => warnings.push('ERROR ' + a.join(' ')),
  };
  const ipcMain = makeIpcMain();
  const localWc = options.localWc || makeWebContents(101, 'file:///app/index.html');
  const fsImpl = options.spyFs ? buildFsProxy({ writeOps }) : fs;
  const childProcessMock = {
    spawn: (...a) => { spawnOps.push(a); return { unref() {}, on() {}, once() {} }; },
    execFileSync: () => '',
  };
  const utilsModule = {
    createWindow: options.createWindow || (() => ({ webContents: localWc })),
  };
  let readyResult = null;
  const fakeProcess = Object.assign({}, process, {
    execPath: path.join(options.rootDir || os.tmpdir(), 'Antigravity.exe'),
    env: {},
    argv: ['electron'],
    cwd: () => options.rootDir || os.tmpdir(),
  });
  const appMock = {
    requestSingleInstanceLock: () => true,
    setPath: () => {},
    getPath: () => options.rootDir || os.tmpdir(),
    getVersion: () => '2.33.0-mock',
    isPackaged: false,
    on: () => {},
    whenReady: () => ({
      then: (fn) => { readyResult = fn(); return readyResult; },
    }),
  };
  const sessionMock = {
    defaultSession: { webRequest: { onBeforeSendHeaders: () => {}, onHeadersReceived: () => {} } },
    fromPartition: () => ({ webRequest: { onBeforeSendHeaders: () => {}, onHeadersReceived: () => {} } }),
  };
  const mockElectron = { app: appMock, ipcMain, session: sessionMock };
  const ctx = vm.createContext({
    require: (id) => {
      if (id === 'fs') return fsImpl;
      if (id === 'path') return path;
      if (id === 'child_process') return childProcessMock;
      if (id === 'electron') return mockElectron;
      if (id === './customScheme') return { registerCustomSchemes: () => {} };
      if (id === './ipcHandlers') return { registerIpcHandlers: () => ({ closeContextMenu: () => {} }) };
      if (id === './utils') return utilsModule;
      if (id === './hostStores') return { HostStores: function HostStores() { this.forSender = () => ({}); } };
      throw new Error('Unexpected require in synthetic main: ' + id);
    },
    process: fakeProcess,
    console: fakeConsole,
    Buffer,
    setTimeout,
    clearTimeout,
  });
  ctx.globalThis = ctx;
  let fatal = null;
  try {
    vm.runInContext(mainSrc, ctx, { filename: 'main.js' });
  } catch (e) {
    fatal = e;
  }
  if (!fatal && readyResult) {
    try { await readyResult; } catch (e) { fatal = e; }
  }
  return { handlers: ipcMain.handlers, warnings, writeOps, spawnOps, ipcMain, utilsModule, localWc, fatal, ctx };
}

// ---------------------------------------------------------------------------
// Preload VM harness
// ---------------------------------------------------------------------------
function runPreloadInVm(preloadSrc, isRemote) {
  const exposed = [];
  const exposedMap = new Map();
  const argv = isRemote ? ['electron', 'preload.js', '--agy-backend=ssh'] : ['electron', 'preload.js'];
  const fakeWindow = {
    addEventListener: () => {}, removeEventListener: () => {}, dispatchEvent: () => true,
    location: { reload: () => {} },
  };
  const fakeDoc = { readyState: 'loading', addEventListener: () => {}, removeEventListener: () => {} };
  const mockElectron = {
    contextBridge: {
      exposeInMainWorld: (key, api) => {
        exposed.push({ key, api });
        exposedMap.set(key, (exposedMap.get(key) || 0) + 1);
      },
    },
    ipcRenderer: { invoke: () => Promise.resolve(null), on: () => {}, removeListener: () => {} },
    webFrame: { executeJavaScript: () => Promise.resolve(null) },
  };
  const ctx = vm.createContext({
    require: (id) => {
      if (id === 'electron') return mockElectron;
      throw new Error('Unexpected require in synthetic preload: ' + id);
    },
    process: { ...process, argv },
    window: fakeWindow,
    document: fakeDoc,
    CustomEvent: function CustomEvent(name) { this.type = name; },
    console,
    setTimeout,
    clearTimeout,
    URL,
  });
  vm.runInContext(preloadSrc, ctx, { filename: 'preload.js' });
  return { exposed, exposedMap };
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------
async function runAll() {
  const rootTmp = fs.mkdtempSync(path.join(os.tmpdir(), 'agm-ipcsec-'));
  try {
    // ---------------- Part A: direct authorization core ----------------
    const logs = [];
    const gate = AUTH_CORE.createIpcAuthorizer({ logger: (ch, reason) => logs.push(ch + ' ' + reason) });
    const ipcMain = makeIpcMain();
    let executed = 0;
    const guarded = gate.wrapHandle(ipcMain, 'hakimi:probe', (_event, value) => { executed++; return value; });
    void guarded;

    const localWc = makeWebContents(1, 'file:///app/index.html');
    const registered = gate.register(localWc, 'test.local');
    const localEvent = eventFor(localWc);

    // SEC-01: legal local main frame allowed
    let sec01 = false;
    try { sec01 = invokeSync(ipcMain, 'hakimi:probe', localEvent, 'ok') === 'ok' && executed === 1; } catch (_) {}
    check('SEC-01', '合法本地主 Frame 允许（真实授权函数）', registered && sec01, { registered, executed });

    // SEC-02: remote WebContents denied
    const remoteWc = makeWebContents(2, 'https://remote.example/app');
    const r02 = expectDenied(ipcMain, 'hakimi:probe', eventFor(remoteWc), 'x');
    check('SEC-02', '远程 WebContents 调用被拒绝', r02.denied && r02.error.message === 'unauthorized' && executed === 1, { reason: gate.denyReason(eventFor(remoteWc)), executed });

    // SEC-03: remote page direct invoke denied
    const remotePage = makeWebContents(3, 'https://evil.example/page');
    let sec03 = true;
    const reasons03 = [];
    for (const ch of CHANNELS) {
      const g = gate.wrapHandle(makeIpcMain(), ch, () => { throw new Error('SHOULD_NOT_RUN'); });
      void g;
    }
    // Use the already wrapped probe for a direct remote page call; also verify all
    // channel names would be denied by the same shared gate logic.
    const r03 = expectDenied(ipcMain, 'hakimi:probe', eventFor(remotePage), 'x');
    sec03 = r03.denied && r03.error.message === 'unauthorized';
    for (const ch of CHANNELS) reasons03.push(gate.denyReason(eventFor(remotePage, makeFrame('https://evil.example/frame'))));
    check('SEC-03', '远程页面直接调用 hakimi:* 通道被拒绝', sec03 && reasons03.every((r) => r === 'untrusted-sender'), { sec03, reasons03: [...new Set(reasons03)] });

    // SEC-04: unknown WebContents denied
    const unknownWc = makeWebContents(404, 'file:///app/index.html');
    const r04 = expectDenied(ipcMain, 'hakimi:probe', eventFor(unknownWc), 'x');
    check('SEC-04', '未登记的未知 WebContents 被拒绝', r04.denied && gate.denyReason(eventFor(unknownWc)) === 'untrusted-sender', gate.denyReason(eventFor(unknownWc)));

    // SEC-04b: local-looking window created for the remote SSH backend is not registered
    const flagGate = AUTH_CORE.createIpcAuthorizer({ logger: () => {} });
    const flagWc = makeWebContents(405, 'file:///app/index.html');
    flagWc.getLastWebPreferences = () => ({ additionalArguments: ['--agy-backend=ssh'] });
    const flagUtils = { createWindow: () => ({ webContents: flagWc }) };
    const flagHook = flagGate.installCreateWindowHook(flagUtils, 'test.remote-flag');
    const flagWin = flagUtils.createWindow('file:///app/index.html');
    const flagIpc = makeIpcMain();
    flagGate.wrapHandle(flagIpc, 'hakimi:probe', () => 'LEAK');
    const flagDenied = expectDenied(flagIpc, 'hakimi:probe', eventFor(flagWc)).denied;
    check('SEC-04b', '远程 SSH 后端标记的窗口不登记（--agy-backend=ssh）', flagHook && flagWin && !flagGate.isRegistered(flagWc) && flagDenied, { flagHook, registered: flagGate.isRegistered(flagWc), denied: flagDenied });

    // SEC-05: child frame denied
    const childFrame = makeFrame('https://ads.example/iframe');
    const r05 = expectDenied(ipcMain, 'hakimi:probe', eventFor(localWc, childFrame), 'x');
    check('SEC-05', '合法窗口中的非可信子 Frame 被拒绝', r05.denied && gate.denyReason(eventFor(localWc, childFrame)) === 'not-main-frame', gate.denyReason(eventFor(localWc, childFrame)));

    // SEC-06: null senderFrame denied
    const r06 = expectDenied(ipcMain, 'hakimi:probe', { sender: localWc, senderFrame: null }, 'x');
    const r06b = expectDenied(ipcMain, 'hakimi:probe', { sender: localWc }, 'x');
    check('SEC-06', 'senderFrame 为 null/缺失时拒绝', r06.denied && r06b.denied && gate.denyReason({ sender: localWc, senderFrame: null }) === 'missing-frame', { nullFrame: r06.denied, absentFrame: r06b.denied });

    // SEC-07: destroyed sender denied
    const destroyedWc = makeWebContents(7, 'file:///app/index.html');
    gate.register(destroyedWc, 'test.destroyed');
    destroyedWc.destroyed = true;
    const r07 = expectDenied(ipcMain, 'hakimi:probe', eventFor(destroyedWc), 'x');
    check('SEC-07', 'sender 已销毁时拒绝', r07.denied && gate.denyReason(eventFor(destroyedWc)) === 'sender-destroyed', gate.denyReason(eventFor(destroyedWc)));

    // SEC-08: navigation revokes old authorization
    const navWc = makeWebContents(8, 'file:///app/index.html');
    gate.register(navWc, 'test.nav');
    navWc.emit('did-finish-load');
    const beforeNav = !expectDenied(ipcMain, 'hakimi:probe', eventFor(navWc), 'before').denied;
    navWc.mainFrame.url = 'https://remote.example/after-nav';
    navWc.emit('did-start-navigation', {}, 'https://remote.example/after-nav', false, true);
    const afterNav = expectDenied(ipcMain, 'hakimi:probe', eventFor(navWc), 'after');
    const reason08 = gate.denyReason(eventFor(navWc));
    check('SEC-08', '主帧跨文档导航后旧授权失效', beforeNav && afterNav.denied && reason08 === 'untrusted-sender', { beforeNav, afterNav: afterNav.denied, reason08 });

    // SEC-08b: same-document navigation does not revoke
    const spaWc = makeWebContents(88, 'file:///app/index.html');
    gate.register(spaWc, 'test.spa');
    spaWc.emit('did-finish-load');
    spaWc.emit('did-start-navigation', { isMainFrame: true, isSameDocument: true }, 'file:///app/index.html#x', true, true);
    const spaAllowed = !expectDenied(ipcMain, 'hakimi:probe', eventFor(spaWc), 'spa').denied;
    check('SEC-08b', '同文档导航不撤销授权（避免误伤 SPA）', spaAllowed);

    // SEC-08c: an initial redirect to a clearly remote origin revokes trust
    const redirWc = makeWebContents(89, 'file:///app/index.html');
    gate.register(redirWc, 'test.redirect');
    redirWc.emit('did-start-navigation', {}, 'https://remote.example/redirected', false, true);
    const afterRedirect = expectDenied(ipcMain, 'hakimi:probe', eventFor(redirWc), 'redirected');
    check('SEC-08c', '初始加载即重定向到远程源时撤销授权', afterRedirect.denied && gate.denyReason(eventFor(redirWc)) === 'untrusted-sender', { denied: afterRedirect.denied });

    // SEC-09: window destroyed revokes old authorization
    const closeWc = makeWebContents(9, 'file:///app/index.html');
    gate.register(closeWc, 'test.close');
    closeWc.emit('did-finish-load');
    const beforeClose = !expectDenied(ipcMain, 'hakimi:probe', eventFor(closeWc), 'before').denied;
    closeWc.destroyed = true;
    closeWc.emit('destroyed');
    const afterClose = expectDenied(ipcMain, 'hakimi:probe', eventFor(closeWc), 'after');
    check('SEC-09', '窗口关闭后旧授权失效', beforeClose && afterClose.denied && gate.denyReason(eventFor(closeWc)) === 'sender-destroyed', { beforeClose, afterClose: afterClose.denied });

    // SEC-10: forged renderer parameters cannot authorize
    let forgedExecuted = 0;
    const forgeIpc = makeIpcMain();
    gate.wrapHandle(forgeIpc, 'hakimi:forge', () => { forgedExecuted++; return 'LEAK'; });
    const forgedEvent = {
      sender: remoteWc,
      senderFrame: remoteWc.mainFrame,
      windowId: localWc.id,
      url: 'http://localhost/',
      isLocal: true,
      local: true,
    };
    const forgedPayload = { windowId: localWc.id, senderId: localWc.id, url: 'file:///app/index.html', local: true, isRemote: false };
    const r10 = expectDenied(forgeIpc, 'hakimi:forge', forgedEvent, forgedPayload);
    check('SEC-10', '伪造 renderer 参数（窗口 ID / URL / local 标记）不能获授权', r10.denied && forgedExecuted === 0 && r10.error.message === 'unauthorized', { denied: r10.denied, executed: forgedExecuted });

    // SEC-12 (direct): unauthorized call has zero side effects
    const sideIpc = makeIpcMain();
    let sideCount = 0;
    for (const ch of CHANNELS) {
      gate.wrapHandle(sideIpc, ch, () => { sideCount++; throw new Error('SHOULD_NOT_RUN'); });
    }
    const sideResults = CHANNELS.map((ch) => expectDenied(sideIpc, ch, eventFor(remoteWc), {}));
    check('SEC-12a', '13 通道未授权调用 handler 执行次数为 0', sideResults.every((r) => r.denied) && sideCount === 0, { sideCount, denied: sideResults.filter((r) => r.denied).length });

    // SEC-18: alternating legal/illegal calls do not bleed state
    let bleedOk = true;
    const bleedDetails = [];
    const executedBeforeBleed = executed;
    for (let i = 0; i < 20; i++) {
      const good = !expectDenied(ipcMain, 'hakimi:probe', eventFor(localWc), 'v' + i).denied;
      const bad = expectDenied(ipcMain, 'hakimi:probe', eventFor(remoteWc), 'bad' + i).denied;
      if (!good || !bad) { bleedOk = false; bleedDetails.push({ i, good, bad }); }
    }
    const executedAfter = executed;
    check('SEC-18', '合法与非法调用交替时授权状态不串扰', bleedOk && executedAfter === executedBeforeBleed + 20, { bleedOk, executedBeforeBleed, executedAfter });

    // Log/error sanitization
    const probeError = expectDenied(ipcMain, 'hakimi:probe', eventFor(remoteWc), 'x').error;
    const badLogs = logs.filter((line) => {
      const lowered = line.toLowerCase();
      return line.includes(os.tmpdir()) || line.includes(os.userInfo().username) || /[a-z]:\\/i.test(line) || lowered.includes('token') || lowered.includes('cookie') || line.includes('/home/') || line.includes('/workspace/');
    });
    check(
      'SEC-LOG-1',
      '拒绝错误信息与日志不含路径、用户名、Token、Cookie',
      probeError && probeError.message === 'unauthorized' && badLogs.length === 0,
      { message: probeError && probeError.message, badLogs }
    );

    // ---------------- Part B: patched main process ----------------
    const dir2330 = path.join(rootTmp, 'fixture_2330');
    const yml2330 = writeSyntheticTargetDir(dir2330, '2.33.0');
    const patch2330 = runPatcher(dir2330, yml2330);
    const main2330 = fs.readFileSync(path.join(dir2330, 'dist', 'main.js'), 'utf8');
    const preload2330 = fs.readFileSync(path.join(dir2330, 'dist', 'preload.js'), 'utf8');

    // SEC-11: enumerate the real registration result
    const vm2330 = await loadPatchedMain(main2330, { rootDir: path.join(rootTmp, 'vm2330') });
    const registeredNames = [...vm2330.handlers.keys()].sort();
    const expectedNames = [...CHANNELS].sort();
    const allWrapped = registeredNames.every((ch) => vm2330.handlers.get(ch).__agmIpcSecWrapped === true);
    const gateResults = registeredNames.map((ch) => expectDenied({ handlers: vm2330.handlers }, ch, eventFor(remoteWc)));
    const namesMatch = JSON.stringify(registeredNames) === JSON.stringify(expectedNames);
    check(
      'SEC-11',
      '真实枚举注册结果：13 个 hakimi:* 通道全部经过门禁',
      !vm2330.fatal && namesMatch && registeredNames.length === 13 && allWrapped && gateResults.every((r) => r.denied && r.error.message === 'unauthorized'),
      { fatal: vm2330.fatal && vm2330.fatal.message, registeredNames, namesMatch, allWrapped, denied: gateResults.filter((r) => r.denied).length, errors: vm2330.warnings.slice(0, 3) }
    );

    // SEC-12 (patched): zero file/process side effects on unauthorized calls
    const spyRoot = path.join(rootTmp, 'spy_fixture');
    const spyYml = writeSyntheticTargetDir(spyRoot, '2.33.0');
    const spyPatch = runPatcher(spyRoot, spyYml);
    const spyMain = fs.readFileSync(path.join(spyRoot, 'dist', 'main.js'), 'utf8');
    const spyVm = await loadPatchedMain(spyMain, { rootDir: path.join(rootTmp, 'spyroot'), spyFs: true });
    const spyBefore = snapshotDirHashes(spyRoot);
    const spyResults = [...spyVm.handlers.keys()].map((ch) => expectDenied({ handlers: spyVm.handlers }, ch, eventFor(remoteWc), 'repo', 'x'));
    const spyAfter = snapshotDirHashes(spyRoot);
    check(
      'SEC-12b',
      '未授权调用无文件/进程/其他特权副作用（13 通道，spy 计数为 0、临时目录零写入）',
      spyPatch.status === 0 && !spyVm.fatal && spyResults.every((r) => r.denied) && spyVm.writeOps.length === 0 && spyVm.spawnOps.length === 0 && JSON.stringify(spyBefore) === JSON.stringify(spyAfter),
      { patchStatus: spyPatch.status, writeOps: spyVm.writeOps, spawnOps: spyVm.spawnOps.length, fsChanged: JSON.stringify(spyBefore) !== JSON.stringify(spyAfter), fatal: spyVm.fatal && spyVm.fatal.message }
    );

    // SEC-13: authorized calls keep original behavior
    const goodRoot = path.join(rootTmp, 'goodroot');
    fs.mkdirSync(goodRoot, { recursive: true });
    const goodWc = makeWebContents(501, 'file:///app/index.html');
    const goodVm = await loadPatchedMain(main2330, { rootDir: goodRoot, localWc: goodWc });
    const goodEvent = eventFor(goodWc);
    let behaviorOk = !goodVm.fatal;
    const behavior = {};
    try {
      behavior.pluginsDir = invokeSync({ handlers: goodVm.handlers }, 'hakimi:get-plugins-dir', goodEvent);
      behavior.hostInfo = invokeSync({ handlers: goodVm.handlers }, 'hakimi:get-host-info', goodEvent);
      behavior.listPlugins = invokeSync({ handlers: goodVm.handlers }, 'hakimi:list-plugins', goodEvent);
      behavior.saveConfig = invokeSync({ handlers: goodVm.handlers }, 'hakimi:save-config', goodEvent, { probe: 1 });
      behavior.readConfig = invokeSync({ handlers: goodVm.handlers }, 'hakimi:read-config', goodEvent);
      behavior.writeState = invokeSync({ handlers: goodVm.handlers }, 'hakimi:write-state', goodEvent, 'registry', '', { version: 1, settings: { a: 1 }, plugins: {} });
      behavior.readState = invokeSync({ handlers: goodVm.handlers }, 'hakimi:read-state', goodEvent, 'registry', '');
      behavior.listPackages = invokeSync({ handlers: goodVm.handlers }, 'hakimi:list-packages', goodEvent, 'repo');
      behavior.readPackageEntry = invokeSync({ handlers: goodVm.handlers }, 'hakimi:read-package-entry', goodEvent, 'nope', 'index.js');
      behavior.installPackage = invokeSync({ handlers: goodVm.handlers }, 'hakimi:install-package', goodEvent, 'nope');
      behavior.uninstallPackage = invokeSync({ handlers: goodVm.handlers }, 'hakimi:uninstall-package', goodEvent, 'nope');
      behavior.readPlugin = invokeSync({ handlers: goodVm.handlers }, 'hakimi:read-plugin', goodEvent, 'missing.js');
      const expectedPlugins = path.join(goodRoot, 'plugins');
      behaviorOk = behavior.pluginsDir === expectedPlugins &&
        behavior.hostInfo && behavior.hostInfo.appVersion === '2.33.0-mock' &&
        Array.isArray(behavior.listPlugins) &&
        behavior.saveConfig === true &&
        behavior.readConfig && behavior.readConfig.probe === 1 &&
        behavior.writeState && behavior.writeState.ok === true &&
        behavior.readState && behavior.readState.settings && behavior.readState.settings.a === 1 &&
        Array.isArray(behavior.listPackages) &&
        behavior.readPackageEntry && behavior.readPackageEntry.ok === false &&
        behavior.installPackage && behavior.installPackage.ok === false &&
        behavior.uninstallPackage && behavior.uninstallPackage.ok === true &&
        behavior.readPlugin === null;
    } catch (e) {
      behaviorOk = false;
      behavior.error = e.message;
    }
    check('SEC-13', '合法调用保持原参数与原返回行为', behaviorOk, behavior);

    // ---------------- Part C: patch idempotency / failure ----------------
    // SEC-14: duplicate registration & duplicate patch are idempotent
    const idemGate = AUTH_CORE.createIpcAuthorizer({ logger: () => {} });
    const idemWc = makeWebContents(601);
    idemGate.register(idemWc, 'a');
    idemGate.register(idemWc, 'a');
    const idemIpc = makeIpcMain();
    let idemCalls = 0;
    idemGate.wrapHandle(idemIpc, 'hakimi:dup', () => { idemCalls++; return 1; });
    idemGate.wrapHandle(idemIpc, 'hakimi:dup', () => { idemCalls++; return 2; });
    const idemInvoke = invokeSync(idemIpc, 'hakimi:dup', eventFor(idemWc));
    const idemDir = path.join(rootTmp, 'idem_hakimi');
    const support = createSyntheticSupportFiles();
    const idemYml = writeSyntheticTargetDir(idemDir, '2.33.0', {
      'dist/main.js': main2330,
      'dist/utils.js': fs.readFileSync(path.join(dir2330, 'dist', 'utils.js'), 'utf8'),
      'dist/preload.js': preload2330,
      'dist/updater.js': support['dist/updater.js'],
      'dist/ipcHandlers.js': support['dist/ipcHandlers.js'],
      'dist/languageServer.js': support['dist/languageServer.js'],
    });
    const idemBefore = ['dist/main.js', 'dist/utils.js', 'dist/preload.js'].map((f) => sha256File(path.join(idemDir, ...f.split('/'))));
    const idemPatch = runPatcher(idemDir, idemYml);
    const idemAfter = ['dist/main.js', 'dist/utils.js', 'dist/preload.js'].map((f) => sha256File(path.join(idemDir, ...f.split('/'))));
    const fullBefore = snapshotDirHashes(dir2330);
    const fullRerun = runPatcher(dir2330, path.join(dir2330, 'app-update.yml'));
    const fullAfter = snapshotDirHashes(dir2330);
    const markerCount = (main2330.match(/AGM_IPC_SEC_GATE_V1/g) || []).length;
    const secureCount = (main2330.match(/secureHandle\('hakimi:/g) || []).length;
    const unwrappedCount = (main2330.match(/electron_1\.ipcMain\.handle\('hakimi:/g) || []).length;
    check(
      'SEC-14',
      '重复注册与重复补丁幂等（单 handler、单门禁、二次补丁零差异）',
      idemGate.size() === 1 && idemIpc.handlers.size === 1 && idemCalls === 1 && idemInvoke === 2 &&
        idemPatch.status === 0 && JSON.stringify(idemBefore) === JSON.stringify(idemAfter) &&
        fullRerun.status === 2 && JSON.stringify(fullBefore) === JSON.stringify(fullAfter) &&
        markerCount >= 1 && secureCount === 13 && unwrappedCount === 0,
      { idemSize: idemGate.size(), handlerSize: idemIpc.handlers.size, idemCalls, idemInvoke, idemStatus: idemPatch.status, fullStatus: fullRerun.status, markerCount, secureCount, unwrappedCount }
    );

    // SEC-15: unknown anchor / authorization insertion failure => exit 2, zero writes
    const failResults = {};
    let sec15 = true;
    {
      const d = path.join(rootTmp, 'neg_anchor');
      const y = writeSyntheticTargetDir(d, '2.33.0');
      const mp = path.join(d, 'dist', 'main.js');
      fs.writeFileSync(mp, fs.readFileSync(mp, 'utf8').replace('(0, customScheme_1.registerCustomSchemes)();', '(0, customScheme_1.registerCustomSchemesX)();'), 'utf8');
      const before = snapshotDirHashes(d);
      const r = runPatcher(d, y);
      const after = snapshotDirHashes(d);
      failResults.anchor = { status: r.status, zeroWrite: JSON.stringify(before) === JSON.stringify(after) };
      sec15 = sec15 && r.status === 2 && failResults.anchor.zeroWrite;
    }
    {
      const d = path.join(rootTmp, 'neg_auth_insert');
      const y = writeSyntheticTargetDir(d, '2.33.0');
      const mp = path.join(d, 'dist', 'main.js');
      const src = fs.readFileSync(mp, 'utf8').replace('(0, customScheme_1.registerCustomSchemes)();', 'const registerHakimiIpcHandlers = 1;');
      fs.writeFileSync(mp, src, 'utf8');
      const before = snapshotDirHashes(d);
      const r = runPatcher(d, y);
      const after = snapshotDirHashes(d);
      failResults.authInsert = { status: r.status, zeroWrite: JSON.stringify(before) === JSON.stringify(after), stderr: r.stderr.slice(0, 300) };
      sec15 = sec15 && r.status === 2 && failResults.authInsert.zeroWrite;
    }
    check('SEC-15', '未知锚点或授权插入失败时补丁失败退出且零写盘', sec15, failResults);

    // SEC-16: both 2.32.1 and 2.33.0 synthetic fixtures pass
    const sec16Details = {};
    let sec16 = true;
    for (const ver of ['2.32.1', '2.33.0']) {
      const d = path.join(rootTmp, 'ver_' + ver.replace(/\./g, '_'));
      const y = writeSyntheticTargetDir(d, ver);
      const r = runPatcher(d, y);
      const mainSrc = fs.readFileSync(path.join(d, 'dist', 'main.js'), 'utf8');
      let syntaxOk = true;
      for (const f of ['dist/main.js', 'dist/utils.js', 'dist/preload.js', 'dist/updater.js', 'dist/ipcHandlers.js', 'dist/languageServer.js']) {
        syntaxOk = syntaxOk && spawnSync(process.execPath, ['--check', path.join(d, ...f.split('/'))], { encoding: 'utf8' }).status === 0;
      }
      const wc = makeWebContents(700 + (ver === '2.32.1' ? 1 : 2));
      const v = await loadPatchedMain(mainSrc, { rootDir: path.join(rootTmp, 'vroot_' + ver.replace(/\./g, '_')), localWc: wc });
      let allowed = false;
      let denied = false;
      try { allowed = invokeSync({ handlers: v.handlers }, 'hakimi:get-plugins-dir', eventFor(wc)).endsWith('plugins'); } catch (_) {}
      denied = expectDenied({ handlers: v.handlers }, 'hakimi:get-plugins-dir', eventFor(remoteWc)).denied;
      const okThis = r.status === 0 && syntaxOk && !v.fatal && v.handlers.size === 13 && allowed && denied;
      sec16 = sec16 && okThis;
      sec16Details[ver] = { patchStatus: r.status, syntaxOk, registered: v.handlers.size, allowed, denied, fatal: v.fatal && v.fatal.message };
    }
    check('SEC-16', '2.32.1 与 2.33.0 合成夹具均通过授权门禁与语法检查', sec16, sec16Details);

    // SEC-17: preload remote branch does not expose local privileged bridge
    const localPre = runPreloadInVm(preload2330, false);
    const remotePre = runPreloadInVm(preload2330, true);
    const localHost = localPre.exposed.find((e) => e.key === 'hakimiHost');
    check(
      'SEC-17',
      'preload 远程分支不暴露本地特权桥接（hakimiHost 仅本地）',
      Boolean(localHost) && Object.keys(localHost.api).length === 13 &&
        !remotePre.exposedMap.has('hakimiHost') &&
        remotePre.exposedMap.get('sshRemote') === 1 &&
        localPre.exposedMap.get('hakimiHost') === 1,
      { localKeys: [...localPre.exposedMap.keys()], remoteKeys: [...remotePre.exposedMap.keys()] }
    );

    // The patch must have succeeded before the VM tests were meaningful.
    check('SEC-00', '2.33.0 合成夹具补丁成功（前置条件）', patch2330.status === 0, { status: patch2330.status, stderr: patch2330.stderr.slice(0, 300) });
    check('SEC-00b', 'spy 合成夹具补丁成功（前置条件）', spyPatch.status === 0, { status: spyPatch.status });
  } finally {
    fs.rmSync(rootTmp, { recursive: true, force: true });
  }

  const failCount = results.filter((r) => r.status === 'FAIL').length;
  const skipCount = results.filter((r) => r.status === 'SKIP').length;
  const passCount = results.filter((r) => r.status === 'PASS').length;
  console.log(`SUMMARY pass=${passCount} fail=${failCount} skip=${skipCount}`);
  process.exitCode = failCount ? 1 : 0;
}

runAll().catch((err) => {
  console.error('FATAL', err && err.stack ? err.stack : err);
  process.exitCode = 1;
});
